__NUXT_JSONP__("/rumbo-democratico/columnas", (function(a,b,c,d,e,f,g,h,i,j,k){return {data:[{columnas:[{slug:"lineamientos_sobre_datos_abiertos_que_hay_de_nuevo",title:"Lineamientos sobre datos abiertos: ¿qué hay de nuevo?",date:"2025-10-16T15:49:01.047Z",img:"https:\u002F\u002Fucarecdn.com\u002Fefdbe729-0f8d-4dab-9dc5-3e359716ba15\u002F",autor:"Dalia Toledo",medio:d,link:"https:\u002F\u002Fanimalpolitico.com\u002Fanalisis\u002Finvitades\u002Flineamientos-sobre-datos-abiertos-que-hay-de-nuevo",category:a,extracto:"Abrir datos no es suficiente; el verdadero valor está en fomentar su uso, en aprovecharlos para impulsar el crecimiento, mejorar el bienestar de las personas y generar decisiones más informadas. Sin esta estrategia, los datos pueden quedar ahí, abiertos, pero sin ser usados para generar valor público.",toc:[],dir:b,path:"\u002Fcolumnas\u002Flineamientos_sobre_datos_abiertos_que_hay_de_nuevo",extension:c,createdAt:g,updatedAt:g},{slug:"democracia_liberal_modelo_en_crisis_o_en_evolucion",title:"Democracia liberal: ¿modelo en crisis o en evolución?",date:"2025-10-08T19:28:20.706Z",img:"https:\u002F\u002Fucarecdn.com\u002F9e68a8e1-502b-4f9b-8631-1208cfa4490d\u002F",autor:" Javier González y Ribka Espinoza",medio:f,link:"https:\u002F\u002Festepais.com\u002Ftendencias_y_opiniones\u002Fdemocracia-liberal-modelo-crisis-o-evolucion\u002F",category:a,extracto:"Ante el deterioro político en diversas partes del globo, Javier González y Ribka Espinoza discuten sobre la necesidad de fortalecer las democracias con instituciones sólidas, educación cívica y transparencia gubernamental.",toc:[],dir:b,path:"\u002Fcolumnas\u002Fdemocracia_liberal_modelo_en_crisis_o_en_evolucion",extension:c,createdAt:"2025-11-25T01:24:03.234Z",updatedAt:"2025-11-25T01:24:03.235Z"},{slug:"entre_desafios_y_posibilidades_hacia_una_reforma_judicial_centrada_en_las_personas",title:"Entre desafíos y posibilidades: hacia una reforma judicial centrada en las personas",date:"2025-09-29T20:54:36.250Z",img:"https:\u002F\u002Fucarecdn.com\u002Fdb9563a6-d2a8-4dfa-a40a-68f1c03ec0cf\u002F","img-alt":"Sistema de justicia",autor:"Brandon Fischer",medio:d,link:"https:\u002F\u002Fanimalpolitico.com\u002Fanalisis\u002Finvitades\u002Fdesafios-posibilidades-reforma-judicial-centrada-personas",category:a,extracto:"Aunque la responsabilidad de garantizar un mayor acceso a la justicia recae en las instituciones competentes, corresponde a todas y todos en el país monitorear su desempeño, exigir rendición de cuentas y demandar un sistema que ponga a las personas en el centro, con enfoque de género y derechos humanos.",toc:[{id:"construyendo-una-justicia-centrada-en-las-personas",depth:2,text:"Construyendo una justicia centrada en las personas"}],dir:b,path:"\u002Fcolumnas\u002Fentre_desafios_y_posibilidades_hacia_una_reforma_judicial_centrada_en_las_personas",extension:c,createdAt:h,updatedAt:h},{slug:"por_que_se_corrompio_la_marina",title:"¿Por qué se corrompió la Marina?",date:"2025-09-23T16:45:29.029Z",img:"https:\u002F\u002Fucarecdn.com\u002F7faa91a0-ef0e-454c-b0a4-9707c5085126\u002F","img-alt":"Secretaría de Marina",autor:"Emiliano Montes de Oca",medio:"Expansión",link:"https:\u002F\u002Fpolitica.expansion.mx\u002Fvoces\u002F2025\u002F09\u002F19\u002Fcolumnainvitada-por-que-se-corrompio-la-marina",category:a,extracto:"Si bien desconocemos los motivos de todas las personas que conforman la red de corrupción que se está investigando, es claro que estos no distan mucho de los de cualquier otra persona que incurre en actos de corrupción.",toc:[],dir:b,path:"\u002Fcolumnas\u002Fpor_que_se_corrompio_la_marina",extension:c,createdAt:i,updatedAt:i},{slug:"hacia_donde_se_dirige_la_democracia_mexicana",title:"¿Hacia dónde se dirige la democracia mexicana?",date:"2025-09-08T22:39:26.065Z",img:"https:\u002F\u002Fucarecdn.com\u002Fee9fb8ac-86a4-457f-862e-38f9cb112e33\u002F",autor:j,medio:f,link:"https:\u002F\u002Festepais.com\u002Ftendencias_y_opiniones\u002Fhacia-donde-dirige-democracia-mexicana\u002F",category:a,extracto:"La historia se construye día con día y la posibilidad de moldearla depende de la comunidad política, de su capacidad de organización y defensa de derechos, de la participación activa y de la exigencia por transparencia y rendición de cuentas.",toc:[],dir:b,path:"\u002Fcolumnas\u002Fhacia_donde_se_dirige_la_democracia_mexicana",extension:c,createdAt:"2025-11-25T01:24:03.242Z",updatedAt:"2025-11-25T01:24:03.243Z"},{slug:"fiscalias_autonomas_en_la_mira_del_poder",title:"Fiscalías autónomas en la mira del poder",date:"2025-06-26T16:30:17.138Z",img:"https:\u002F\u002Fucarecdn.com\u002F6352bbfd-94c7-4c63-8e0e-d23040777b5c\u002F","img-alt":"Fiscalías autónomas",autor:"Liliana Alvarado ",medio:d,link:"https:\u002F\u002Fanimalpolitico.com\u002Fanalisis\u002Finvitades\u002Ffiscalias-autonomas-mira-del-poder",category:a,extracto:"Quitar la autonomía a las fiscalías no soluciona el problema, al contrario, abre la posibilidad de que la procuración de justicia sea usada como un herramienta política. Darle mayor control al ejecutivo sobre las fiscalías, nos alejaría aún más de un estado democrático.",toc:[],dir:b,path:"\u002Fcolumnas\u002Ffiscalias_autonomas_en_la_mira_del_poder",extension:c,createdAt:e,updatedAt:e},{slug:"es_relevante_todavia_tener_un_plan_nacional_de_desarrollo",title:"¿Es relevante todavía tener un Plan Nacional de Desarrollo?",date:"2025-06-18T23:10:52.410Z",img:"https:\u002F\u002Fucarecdn.com\u002Fe5f717a1-fbba-4d0f-a865-d4f222a9c51a\u002F","img-alt":"Plan Nacional de Desarrollo",autor:j,medio:f,link:"https:\u002F\u002Festepais.com\u002Ftendencias_y_opiniones\u002Fplan-nacional-de-desarrollo\u002F",category:a,extracto:"El que no existan consecuencias frente al incumplimiento de las metas expresadas en el Plan Nacional de Desarrollo aporta muchísimo a la ligereza con la que éste se redacta y se le da seguimiento.",toc:[],dir:b,path:"\u002Fcolumnas\u002Fes_relevante_todavia_tener_un_plan_nacional_de_desarrollo",extension:c,createdAt:e,updatedAt:e},{slug:"el_dia_siguiente_ocho_preguntas_para_el_sistema_judicial_que_nos_espera",title:"El día siguiente: ocho preguntas para el sistema judicial que nos espera",date:"2025-06-02T18:22:16.054Z",img:"https:\u002F\u002Fucarecdn.com\u002F76294fbf-5e24-4023-aaef-c9cea7a5b0ee\u002F","img-alt":"Elección judicial",autor:"Javier González y Alejandra Treviño",medio:d,link:"https:\u002F\u002Fanimalpolitico.com\u002Fanalisis\u002Finvitades\u002Fpreguntas-sistema-judicial-que-nos-espera",category:a,extracto:"Prescindiendo de cuál sea la postura respecto a la elección del 1 de junio y las motivaciones de la reforma judicial, lo cierto es que el 2 de junio amaneceremos con un Poder Judicial que ha abierto puertas y ventanas a la injerencia de intereses económicos, políticos o de otra índole en la toma de las decisiones jurisdiccionales.",toc:[],dir:b,path:"\u002Fcolumnas\u002Fel_dia_siguiente_ocho_preguntas_para_el_sistema_judicial_que_nos_espera",extension:c,createdAt:k,updatedAt:k}],total:[{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{}]}],fetch:{},mutations:[]}}("rumbo-democratico","\u002Fcolumnas",".md","Animal Político","2025-11-25T01:24:03.240Z","Este País","2025-11-25T01:24:03.244Z","2025-11-25T01:24:03.239Z","2025-11-25T01:24:03.245Z","Javier González","2025-11-25T01:24:03.237Z")));